const item = $input.item.json;
const text = item.testo_italiano || item.text || "";

// Soglia di sicurezza per ElevenLabs Multilingual v2: max 1500 caratteri per chiamata.
// Limite ufficiale ElevenLabs Creator: 5000 char/chiamata,
// ma testi piu' brevi sono piu' affidabili (meno errori di timeout/rete).
const MAX_CHARS = 1500;

// Pulizia caratteri problematici
let cleanText = text
  .replace(/"/g, "'")
  .replace(/\n/g, ' ')
  .replace(/\r/g, ' ')
  .replace(/\t/g, ' ')
  .replace(/\s+/g, ' ')   // collassa spazi multipli
  .trim();
// NUMERI IN LETTERE per la voce (colonna voice_numbers_in_words = SI): 2.500 -> duemilacinquecento, 1945, 95%, a.C., XIX secolo...
if (String($('Load Channel Config').first().json.voice_numbers_in_words || '').trim().toUpperCase() === 'SI') {
  const U = ['zero','uno','due','tre','quattro','cinque','sei','sette','otto','nove','dieci','undici','dodici','tredici','quattordici','quindici','sedici','diciassette','diciotto','diciannove'];
  const D = ['','','venti','trenta','quaranta','cinquanta','sessanta','settanta','ottanta','novanta'];
  const ORD = ['','primo','secondo','terzo','quarto','quinto','sesto','settimo','ottavo','nono','decimo','undicesimo','dodicesimo','tredicesimo','quattordicesimo','quindicesimo','sedicesimo','diciassettesimo','diciottesimo','diciannovesimo','ventesimo','ventunesimo'];
  const num = (n) => { n = Math.floor(n);
    if (n < 20) return U[n];
    if (n < 100) { const d = Math.floor(n / 10), u = n % 10; let t = D[d]; if (u === 1 || u === 8) t = t.slice(0, -1); return t + (u === 0 ? '' : (u === 3 ? 'tré'.replace('é','e') : U[u])); }
    if (n < 1000) { const c = Math.floor(n / 100), r = n % 100; let t = c === 1 ? 'cento' : U[c] + 'cento'; if (r === 8 || Math.floor(r / 10) === 8) t = t.slice(0, -1); return t + (r ? num(r) : ''); }
    if (n < 1e6) { const m = Math.floor(n / 1000), r = n % 1000; return (m === 1 ? 'mille' : num(m) + 'mila') + (r ? num(r) : ''); }
    if (n < 1e9) { const m = Math.floor(n / 1e6), r = n % 1e6; return (m === 1 ? 'un milione' : num(m) + ' milioni') + (r ? ' ' + (r < 1000 ? 'e ' : '') + num(r) : ''); }
    const m = Math.floor(n / 1e9), r = n % 1e9; return (m === 1 ? 'un miliardo' : num(m) + ' miliardi') + (r ? ' ' + num(r) : ''); };
  const rom = (r) => { const v = { I: 1, V: 5, X: 10 }; let t = 0; for (let i = 0; i < r.length; i++) { const x = v[r[i]] || 0; t += (i + 1 < r.length && (v[r[i + 1]] || 0) > x) ? -x : x; } return t; };
  cleanText = cleanText
    .replace(/\b([IVX]{1,5})\s+secolo/g, (m, r) => (ORD[rom(r)] || r) + ' secolo')
    .replace(/\b([A-Z][a-zà-ÿ]+) (II|III|IV|V|VI|VII|VIII|IX|X|XI|XII|XIII|XIV|XV|XVI)\b/g, (m, a, r) => a + ' ' + ORD[rom(r)])
    .replace(/\ba\.\s?C\./g, 'avanti Cristo').replace(/\bd\.\s?C\./g, 'dopo Cristo')
    .replace(/(\d)\s*%/g, '$1 per cento').replace(/(\d)\s*°\s*C?\b/g, '$1 gradi')
    .replace(/(\d)\s*km\b/g, '$1 chilometri').replace(/(\d)\s*kg\b/g, '$1 chili').replace(/(\d)\s*€/g, '$1 euro').replace(/€\s*(\d)/g, '$1 euro')
    .replace(/\b\d{1,3}(?:[.\u202f ]\d{3})+\b/g, (m) => m.replace(/\D/g, ''))
    .replace(/\b(\d+),(\d+)\b/g, (m, a, b) => num(+a) + ' virgola ' + (b.startsWith('0') ? b.split('').map(x => U[+x]).join(' ') : num(+b)))
    .replace(/\b\d{1,12}\b/g, (m) => num(+m))
    .replace(/\buno (milion|miliard)/g, 'un $1');
}
// Validazione: scene vuote non vanno inviate a ElevenLabs
if (!cleanText) {
  cleanText = '<break time="1.5s" />';  // placeholder per evitare chiamata API vuota
  console.log(`WARNING: scena ${item.index} con testo vuoto, uso placeholder`);
}

// Troncamento di sicurezza
if (cleanText.length > MAX_CHARS) {
  console.log(`WARNING: scena ${item.index} troncata da ${cleanText.length} a ${MAX_CHARS} caratteri`);
  cleanText = cleanText.substring(0, MAX_CHARS - 3) + "...";
}

item.text_clean = cleanText;
item.text_clean_length = cleanText.length;  // utile per debug

return item;

const _sd = $getWorkflowStaticData('global');
_sd.audioMap = {};
_sd.audioCounter = 0;

const animatedCount = parseInt(
  $('Read Production Row').first().json.animated_count
) || 0;

// Scene di apertura forzate a un modo scelto dal foglio (CK = quante, FM = quale)
const _cfgIntro = $('Load Channel Config').first().json;
const characterIntroScenes = parseInt(_cfgIntro.character_intro_scenes) || 0;
const INTRO_MODE = String(_cfgIntro.intro_render_mode || 'character').trim().toLowerCase();

const ZOOM_MAGNITUDE = 2;

return $input.all().map((item, i) => {
  const scene = item.json;
  const idx = i + 1; // index 1-based: la scena 1 è la prima

  // GARANZIA PASSO 0: le prime N scene sono SEMPRE character,
  // a prescindere da cosa ha deciso l'AI Scriptwriter.
  let renderMode = scene.render_mode;
  if (idx <= characterIntroScenes) {
    if (INTRO_MODE === 'stock') {
      // forzo stock SOLO se l'AI ha prodotto una query: senza, Pexels riceve una
      // ricerca vuota e la scena ripiega su texture invece che sull'apertura voluta
      if (String(scene.stock_query || '').trim()) renderMode = 'stock';
      else console.log('Scena ' + idx + ': intro stock richiesta ma stock_query vuota, lascio ' + renderMode);
    } else if (INTRO_MODE === 'typo') {
      renderMode = 'typo';
    } else {
      renderMode = 'character';
    }
  }

    // STOCK AL 100% (colonna stock_percentage = 100): ogni scena diventa stock, nessuna immagine AI.
  // Se l'AI non ha dato una ricerca Pexels, uso a rotazione le ricerche della colonna stock_fallback_query.
  const _pct = Number(String(_cfgIntro.stock_percentage ?? '').replace(',', '.')) || 0;
  if (_pct >= 100 && renderMode !== 'stock') {
    if (!String(scene.stock_query || '').trim()) {
      const _riserva = String(_cfgIntro.stock_fallback_query || 'ancient ruins, marble statue, old library, candle light, misty forest, city at night, ocean waves, mountain sunrise')
        .split(',').map(s => s.trim()).filter(Boolean);
      scene.stock_query = _riserva[(idx - 1) % _riserva.length];
    }
    renderMode = 'stock';
  }
// SOLO SFONDI DEL FOGLIO (colonna stock_solo_riserva = SI): la ricerca Pexels non la decide piu' l'AI
  // (che a volte cerca cose moderne), ma si sceglie dalla colonna stock_fallback_query.
  // Formato di ogni voce: "ricerca pexels: parole chiave" (voci separate da virgola).
  // VARIETA': tra le voci che c'entrano con la scena vince quella usata MENO volte finora nel video;
  // se nessuna c'entra, la meno usata in assoluto. Cosi' lo stesso sfondo non torna di continuo.
  if (String(_cfgIntro.stock_solo_riserva || '').trim().toUpperCase() === 'SI') {
    const _voci = String(_cfgIntro.stock_fallback_query || '').split(',').map(s => s.trim()).filter(Boolean).map(v => {
      const [q, k] = v.split(':');
      return { q: q.trim(), k: String(k || q).toLowerCase().split(/[^a-zàèéìòù]+/).filter(w => w.length > 2) };
    });
    if (_voci.length) {
      const _mem = (typeof _sd !== 'undefined' && _sd) ? _sd : globalThis;
      if (idx === 1 || !_mem.usoSfondi) _mem.usoSfondi = {};
      const _uso = _mem.usoSfondi;
      const _sc = { ...scene };
      if (String(_sc.stock_query || '').includes(':')) delete _sc.stock_query;   // voce di riserva grezza, non una ricerca dell'AI
      const _testo = ' ' + JSON.stringify(_sc).toLowerCase().replace(/[^a-zàèéìòù]+/g, ' ') + ' ';
      const _cand = _voci.map((v, j) => ({ v, j, n: v.k.filter(w => _testo.includes(' ' + w)).length, u: _uso[v.q] || 0 }));
      const _ord = (a, b) => (a.u - b.u) || (b.n - a.n) || (((a.j - idx) % _voci.length + _voci.length) % _voci.length - ((b.j - idx) % _voci.length + _voci.length) % _voci.length);
      const _match = _cand.filter(c => c.n > 0).sort(_ord);
      const _minUso = Math.min(..._cand.map(c => c.u));
      // una voce che c'entra si usa solo se non e' gia' stata usata piu' delle altre; altrimenti si passa alla meno usata
      const _scelta = (_match.length && _match[0].u <= _minUso + 1) ? _match[0] : _cand.sort(_ord)[0];
      _uso[_scelta.v.q] = (_uso[_scelta.v.q] || 0) + 1;
      console.log('Scena ' + idx + ': sfondo "' + _scelta.v.q + '" (uso n.' + _uso[_scelta.v.q] + ', parole trovate ' + _scelta.n + ')');
      scene.stock_query = _scelta.v.q;
      renderMode = 'stock';
    }
  }
  const isAnimated = idx <= animatedCount;
  const isStock = renderMode === 'stock';
  const isTypo = renderMode === 'typo';

const zoom = (isAnimated || isStock || isTypo)
  ? 0
  : (idx % 2 === 1 ? ZOOM_MAGNITUDE : -ZOOM_MAGNITUDE);

  return {
    json: {
      ...scene,
      render_mode: renderMode,
      index: idx,
      is_animated: isAnimated,
      is_stock: isStock,
      is_typo: isTypo,
      zoom: zoom
    }
  };
});

const items = $input.all();
const blocks = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const name = item.json.name || `Esempio ${i + 1}`;

  // Lettura binary robusta (gestisce sia filesystem che in-memory)
  const binaryData = item.binary.data;
  let text;

  if (binaryData.id) {
    const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
    text = buffer.toString('utf-8');
  } else {
    text = Buffer.from(binaryData.data, 'base64').toString('utf-8');
  }

  blocks.push(`========== ${name} ==========\n\n${text.trim()}`);
}

// Limita a 3 script di riferimento per non sforare il rate limit OpenAI TPM
const referenceBlock = blocks.slice(0, 3).join('\n\n---\n\n');

return [{
  json: {
    referenceBlock,
    exampleCount: items.length,
    totalChars: referenceBlock.length,
  }
}];

// Ricostruisce l'URL della copertina YouTube dal Link video del competitor.
// La copertina di qualsiasi video YouTube è accessibile pubblicamente
// a un URL standard ricavato dall'ID del video.

const row = $('Read Production Row').first().json;
const link = row['Link video'] || row['Link_video'] || '';

// Estrae il VIDEO_ID dal link (gestisce watch?v=, youtu.be/, ecc.)
function estraiVideoId(url) {
  if (!url) return '';
  const patterns = [
    /[?&]v=([^&]+)/,        // youtube.com/watch?v=XXXX
    /youtu\.be\/([^?&]+)/,  // youtu.be/XXXX
    /\/embed\/([^?&]+)/,    // youtube.com/embed/XXXX
    /\/shorts\/([^?&]+)/    // youtube.com/shorts/XXXX
  ];
  for (const p of patterns) {
    const m = url.match(p);
    if (m && m[1]) return m[1];
  }
  return '';
}

const videoId = estraiVideoId(link);

// maxresdefault è l'alta risoluzione; se un video non ce l'ha,
// hqdefault esiste SEMPRE come fallback affidabile.
const thumbnailUrl = videoId
  ? `https://img.youtube.com/vi/${videoId}/maxresdefault.jpg`
  : '';
const thumbnailFallback = videoId
  ? `https://img.youtube.com/vi/${videoId}/hqdefault.jpg`
  : '';

return [{
  json: {
    competitor_video_id: videoId,
    competitor_thumbnail_url: thumbnailUrl,
    competitor_thumbnail_fallback: thumbnailFallback,
    competitor_titolo: row['titolo_originale'] || '',
    competitor_link: link
  }
}];

