params.jsCode:
// Pick Clip Pexels — MODE: Run Once for Each Item
// Sceglie il miglior clip Pexels e RI-STAMPA scena (l'API Pexels lo cancella).
// video_urls = TUTTE le clip trovate (una per video, max 1080p): servono al cambio
// clip ogni N secondi (colonna clip_change_seconds). Con la colonna vuota non si usano.

const data = $input.item.json;
// LUOGHI ESCLUSI (colonna stock_exclude_words): clip girate in luoghi in cui il pubblico del canale non si riconosce
const _escludi = String($('Load Channel Config').first().json.stock_exclude_words || '').toLowerCase().split(',').map(s => s.trim()).filter(Boolean);
const videos = (Array.isArray(data.videos) ? data.videos : []).filter(v => !_escludi.some(w => String(v.url || '').toLowerCase().includes(w)));
if (_escludi.length) console.log('Clip Pexels dopo il filtro luoghi: ' + videos.length + ' su ' + (Array.isArray(data.videos) ? data.videos.length : 0));

const MAX_H = 1080;

function migliorFile(video) {
  const files = Array.isArray(video && video.video_files) ? video.video_files : [];
  let url = '', h0 = 0;
  for (const f of files) {
    const h = Number(f.height) || 0;
    const isMp4 = (f.file_type || '').includes('mp4');
    if (isMp4 && h <= MAX_H && h > h0) { h0 = h; url = f.link; }
  }
  return url;
}

let bestUrl = '';
const tutte = [];
for (const video of videos) {
  const u = migliorFile(video);
  if (u && !tutte.includes(u)) tutte.push(u);
  if (!bestUrl && u) bestUrl = u;          // stessa scelta di prima: il primo video valido
}
if (!bestUrl && videos[0] && Array.isArray(videos[0].video_files)) {
  const anyMp4 = videos[0].video_files.find(f => (f.file_type || '').includes('mp4'));
  if (anyMp4) bestUrl = anyMp4.link;
}

// VARIETA' CLIP: se questa ricerca Pexels e' gia' stata usata in scene precedenti dello stesso video,
// si parte da clip diverse dei risultati (non sempre dalle prime), cosi' lo stesso video non si ripete.
try {
  const _qui = $('Classify scenes').item.json;
  const _q = String(_qui.stock_query || '').trim().toLowerCase();
  const _n = Number(_qui.index ?? _qui.scena ?? 0);
  if (_q && tutte.length > 1) {
    const _prima = $('Classify scenes').all()
      .filter(i => String(i.json.stock_query || '').trim().toLowerCase() === _q && Number(i.json.index ?? i.json.scena ?? 0) < _n).length;
    if (_prima > 0) {
      const _da = (_prima * 3) % tutte.length;
      const _ruota = tutte.slice(_da).concat(tutte.slice(0, _da));
      tutte.length = 0;
      _ruota.forEach(u => tutte.push(u));
      bestUrl = tutte[0];
      console.log('Ricerca "' + _q + '" gia\' usata ' + _prima + ' volte: parto dalla clip n.' + (_da + 1) + ' di ' + tutte.length);
    }
  }
} catch (e) { console.log('varieta clip non applicata: ' + e.message); }const scena = $('Classify scenes').item.json.scena ?? $('Classify scenes').item.json.index;

return {
  json: {
    scena: scena,
    video_url: bestUrl,
    video_urls: tutte,
    pexels_found: !!bestUrl,
    pexels_reason: bestUrl ? 'OK' : (videos.length === 0 ? 'Nessun video Pexels per la query' : 'Nessun mp4 utilizzabile')
  }
};

// Accumula Audio — robusto: scena da contatore monotono (1,2,3,...),
// non dal nome file (che collassava sempre a "1_audio").
const sd = $getWorkflowStaticData('global');
if (!sd.audioMap) sd.audioMap = {};
if (typeof sd.audioCounter !== 'number') sd.audioCounter = 0;

// avanza di una scena a ogni audio processato, sempre in ordine
sd.audioCounter += 1;
const scena = sd.audioCounter;

const up = $('Upload file').item.json;
const id = (up && up.id) ? up.id : '';

// scrivo solo se l'upload e' andato a buon fine.
// Se manca l'id, quella scena resta senza audio (gestita a valle),
// ma il contatore avanza comunque: l'allineamento scena<->audio resta corretto.
if (id) {
  sd.audioMap[scena] = 'https://drive.google.com/uc?export=download&id=' + id;
}
// DURATA VOCE (per il cambio clip): mp3 ElevenLabs a 128 kbps -> secondi = byte * 8 / 128000
if (scena === 1) sd.audioDur = {};
try {
  const b = $('HTTP Request').item.binary || {};
  const f = b.data || Object.values(b)[0] || {};
  const m = String(f.fileSize || '').match(/([\d.,]+)\s*(B|kB|KB|MB)/);
  if (m) {
    const n = parseFloat(m[1].replace(',', '.'));
    const mult = m[2] === 'MB' ? 1e6 : (m[2] === 'B' ? 1 : 1000);
    if (!sd.audioDur) sd.audioDur = {};
    sd.audioDur[scena] = Math.round(n * mult * 8 / 128000 * 10) / 10;
  }
} catch (e) { /* senza durata si usa la stima a parole */ }
return $input.item;

const sd = $getWorkflowStaticData('global');
const audioMap = sd.audioMap || {};
return [{ json: { audioMap: audioMap, count: Object.keys(audioMap).length, audioDur: sd.audioDur || {} } }];

// ============================================================
//  NODO n8n  ·  tipo: Code (JavaScript)  ·  nome: "Collect Card URLs"
//  Posizione: DOPO "Render Scene Card" (HCTI), PRIMA di "Code in JavaScript".
//  Cosa fa:
//   - riprende l'item aggregato originale da "Aggregate" (tutti gli array scena);
//   - prende gli URL restituiti da HCTI (uno per card), li allinea per indice
//     di scena usando _card_idx salvato in "Build Card Payloads";
//   - emette UN SOLO item = aggregato originale + nuovo array scene_card_urls.
//  Cosi' "Code in JavaScript" torna a ricevere i dati che si aspetta,
//  piu' gli URL delle card (che useremo allo Step 4).
// ============================================================

const agg = $('Aggregate').first().json;

// numero scene (dalla lunghezza di testo_scena)
const testi = Array.isArray(agg.testo_scena) ? agg.testo_scena : [agg.testo_scena];
const sceneCount = testi.length;

// payload originali (con _card_idx) e risultati HCTI (con url), stesso ordine
const payloads = $('Build Card Payloads').all();
const results = $input.all();

const scene_card_urls = new Array(sceneCount).fill(null);

payloads.forEach((p, i) => {
  const idx = (p.json && typeof p.json._card_idx === 'number') ? p.json._card_idx : -1;
  if (idx < 0) return; // sentinella -> nessuna card
  const res = results[i] ? results[i].json : null;
  const url = res ? (res.url || (res.body && res.body.url) || null) : null;
  if (url) scene_card_urls[idx] = url;
});

return [{ json: { ...agg, scene_card_urls, titolo_italiano: ((($('AI Scriptwriter').first().json.output)||{}).titolo_italiano)||'', row_number: (($('Filter').first().json)||{}).row_number, scriptwriter: ($('AI Scriptwriter').first().json.output)||{}, seo: ($('SEO Generator').first().json.output)||{} } }];

// ============================================================
//  Prepara Blocchi — calcola quanti blocchi servono e affetta
//  la trascrizione. NON chiama Claude: e' istantaneo (<1s).
//  Emette UN item per blocco; il loop li processera' uno a uno.
// ============================================================
const WF_VERSION = '2026-07-24-g';
console.log('WF_VERSION ' + WF_VERSION);

const cfg   = $('Load Channel Config').first().json;

// reset stato loop a inizio giro (sostituisce la pulizia fragile nell'assembler)
const _wf = $getWorkflowStaticData('global');
_wf.allSegments = [];
_wf.capitoli = [];
_wf.runningSummary = '';
_wf.titolo = '';
_wf.renderRetries = 0;
_wf.blockRetries = {};

const row   = $('Read Production Row').first().json;
const merge = $('Merge').first().json;
const biasRaw = $('Bias Analyzer').first().json.output;
const bias = (typeof biasRaw === 'string') ? biasRaw : JSON.stringify(biasRaw);

// dossier di ricerca web (solo se il canale ha web_research_enabled = SI)
let dossier = '';
try {
  const raw = $('Ricerca Azienda').first().json.content || [];
  dossier = Array.isArray(raw)
       ? raw.filter(x => x.type === 'text').map(x => x.text).join('\n').slice(0, 20000)
       : String(raw).slice(0, 20000);
} catch (e) { dossier = ''; }

// tabella target_durata -> [scene totali, range parole]
const TARGET = {
  'test_15s_3s':[5,'6-8'],'test_15s_5s':[3,'11-14'],'test_15s_8s':[2,'18-22'],
  'test_30s_3s':[10,'6-8'],'test_30s_5s':[6,'11-14'],'test_30s_8s':[4,'18-22'],
  'test_1min_3s':[20,'6-8'],'test_1min_5s':[12,'11-14'],'test_1min_8s':[8,'18-22'],
  'corto_4min_3s':[80,'6-8'],'corto_4min_5s':[48,'11-14'],'corto_4min_8s':[30,'18-22'],
  'breve_8min_3s':[160,'6-8'],'breve_8min_5s':[96,'11-14'],'breve_8min_8s':[60,'18-22'],
  'breve_9min_3s':[180,'6-8'],'breve_9min_5s':[108,'11-14'],'breve_9min_8s':[68,'18-22'],
  'breve_10min_3s':[200,'6-8'],'breve_10min_5s':[120,'11-14'],'breve_10min_8s':[75,'18-22'],
  'breve_12min_3s':[240,'6-8'],'breve_12min_5s':[144,'11-14'],'breve_12min_8s':[90,'18-22'],
  'medio_15min_3s':[300,'6-8'],'medio_15min_5s':[180,'11-14'],'medio_15min_8s':[113,'18-22'],
  'lungo_20min_3s':[400,'6-8'],'lungo_20min_5s':[240,'11-14'],'lungo_20min_8s':[150,'18-22'],
};

let td = String(row.target_durata || '').trim();
let conf = TARGET[td];
// === DURATA COME L'ORIGINALE (colonna durata_auto = SI) ===
// Copia la lunghezza del video originale contando le parole della sua trascrizione,
// con un minimo (durata_min_minuti, default 10) e un massimo facoltativo (durata_max_minuti).
// I test (target_durata che inizia con "test_") restano come sono.
if (String(cfg.durata_auto || '').trim().toUpperCase() === 'SI' && !conf) {
  const _t = merge.transcript;
  const _txt = Array.isArray(_t)
    ? _t.map(x => (x && (x.text || x.snippet || x.content)) || (typeof x === 'string' ? x : '')).join(' ')
    : (typeof _t === 'string' ? _t : '');
  const _parole = _txt.split(/\s+/).filter(Boolean).length;
  const _ppm = 156;                                                  // parole al minuto della nostra voce
  const _min = Number(String(cfg.durata_min_minuti ?? '').replace(',', '.')) || 10;
  const _max = Number(String(cfg.durata_max_minuti ?? '').replace(',', '.')) || 0;
  let _minuti = _parole > 300 ? _parole / _ppm : _min;               // trascrizione assente o vuota -> minimo
  _minuti = Math.max(_min, _minuti);
  if (_max > 0) _minuti = Math.min(_max, _minuti);
  const _sc = String(cfg.durata_auto_scena || '5s').trim().replace(/^_/, '');
  const _tab = { '3s': [7, '6-8'], '5s': [12.5, '11-14'], '8s': [20, '18-22'] }[_sc] || [12.5, '11-14'];
  conf = [Math.max(12, Math.round(_minuti * _ppm / _tab[0])), _tab[1]];
  td = 'auto_' + Math.round(_minuti) + 'min_' + _sc;
  console.log('Durata automatica: originale ~' + Math.round(_parole / _ppm) + ' min (' + _parole + ' parole) -> ' + Math.round(_minuti) + ' min, ' + conf[0] + ' scene da ' + _sc);
}
if (!conf) throw new Error('target_durata non riconosciuto: "' + td + '"');
const TOTAL = conf[0];
const WORD_RANGE = conf[1];

// knob parametrici (colonne opzionali nel foglio; default se assenti)
const BLOCK   = parseInt(cfg.scene_per_blocco) || 20;
const MAX_SLICE = 8000;   // max caratteri di trascrizione per blocco
const MAX_REF   = 6000;   // max caratteri script di riferimento

// normalizza trascrizione in testo unico
let transcriptText;
const t = merge.transcript;
if (Array.isArray(t)) {
  transcriptText = t.map(x => (x && (x.text || x.snippet || x.content)) || (typeof x === 'string' ? x : '')).join(' ');
} else {
  transcriptText = (typeof t === 'string') ? t : JSON.stringify(t || '');
}
const referenceBlock = String(merge.referenceBlock || '').slice(0, MAX_REF);

const nBlocks  = Math.ceil(TOTAL / BLOCK);
const sliceLen = Math.ceil(transcriptText.length / nBlocks);

// costruisco un item per ogni blocco
const items = [];
let sceneFrom = 1;
for (let b = 0; b < nBlocks; b++) {
  const scenesThisBlock = Math.min(BLOCK, TOTAL - (sceneFrom - 1));
  if (scenesThisBlock <= 0) break;
  const sceneTo = sceneFrom + scenesThisBlock - 1;
  let slice = transcriptText.slice(b * sliceLen, (b + 1) * sliceLen);
  if (slice.length > MAX_SLICE) slice = slice.slice(0, MAX_SLICE);

  items.push({ json: {
    blockIndex: b,
    nBlocks,
    sceneFrom,
    sceneTo,
    scenesThisBlock,
    wordRange: WORD_RANGE,
    total: TOTAL,
    slice,
    bias,
    dossier,
    referenceBlock,
    titoloOriginale: String(row.titolo_originale || 'Video'),
    wfVersion: WF_VERSION
  }});
  sceneFrom = sceneTo + 1;
}

return items;

// Costruisce system + user per il blocco corrente.
// CAPITOLI: con youtube_chapters_enabled = SI ogni blocco restituisce anche il titolo del suo capitolo.
// Legge lo stato accumulato (scene gia' fatte) dalla variabile statica del workflow.
//
// MODALITA' TITOLO: se la riga non ha Link video, 'slice' arriva vuoto e il video
// si scrive DA ZERO partendo dal titolo e dal dossier di ricerca web.
// Se la trascrizione c'e', il messaggio e' identico a prima, parola per parola.
const cur = $json;  // l'item del blocco corrente (da Prepara Blocchi via Loop)

// stato accumulato finora (persiste tra le iterazioni del loop)
const wfStatic = $getWorkflowStaticData('global');
const allSegments = wfStatic.allSegments || [];
const runningSummary = wfStatic.runningSummary || '';

const systemMessage = $('System Scriptwriter').first().json.system_message;

const b = cur.blockIndex;
const nBlocks = cur.nBlocks;
const sceneFrom = cur.sceneFrom;
const sceneTo = cur.sceneTo;
const scenesThisBlock = cur.scenesThisBlock;

const modoTitolo = !String(cur.slice || '').trim();

// lingua del canale dal foglio (colonna language): in modalita' titolo va dichiarata
// esplicitamente, perche' gli script di riferimento possono essere in un'altra lingua
const LINGUE = { it: 'ITALIANO', en: 'INGLESE', es: 'SPAGNOLO', fr: 'FRANCESE', de: 'TEDESCO', pt: 'PORTOGHESE' };
const codLingua = String($('Load Channel Config').first().json.language || 'it').trim().toLowerCase();
const LINGUA = LINGUE[codLingua] || codLingua.toUpperCase();

// capitoli YouTube (colonna youtube_chapters_enabled): cella vuota = comportamento storico
const CAPITOLI = String($('Load Channel Config').first().json.youtube_chapters_enabled || '').trim().toUpperCase() === 'SI';
// TYPO DISTRIBUITE (colonna typo_spread): cella vuota = comportamento storico
const _cfgT = $('Load Channel Config').first().json;
const TYPO_SPREAD = String(_cfgT.typo_spread || '').trim().toUpperCase() === 'SI';
let regolaTypo = '';
if (TYPO_SPREAD) {
  const totale = Number(cur.total) || 0;
  const intro = parseInt(_cfgT.character_intro_scenes) || 0;
  const typoOn = String(_cfgT.typo_enabled || '').trim().toUpperCase() === 'SI';
  const pct = Number(String(_cfgT.typo_percentage ?? '').replace(',', '.')) || 0;
  const disponibili = totale - intro;
  const T = typoOn ? Math.floor(totale * pct / 100) : 0;
  const posTypo = new Set();
  for (let k = 0; k < T && disponibili > 0; k++) {
    posTypo.add(intro + 1 + Math.floor((k + 0.5) * disponibili / T));
  }
  const qui = [...posTypo].filter(n => n >= sceneFrom && n <= sceneTo).sort((a, b) => a - b);
  console.log('Blocco ' + (b + 1) + ': scene typo assegnate ' + (qui.length ? qui.join(', ') : 'nessuna'));
  regolaTypo = '\n\nPOSIZIONE DELLE SCENE TIPOGRAFICHE (PRIORITARIA SUL PASSO 2-BIS E SULLA QUOTA TYPO): ' +
    (qui.length
      ? 'in questo blocco le scene con render_mode "typo" sono ESATTAMENTE le scene ' + qui.join(', ') + ', ne\' una in piu\' ne\' una in meno. Per ognuna scrivi un\'etichetta_scena forte (cifra, dato o affermazione presente nel testo della scena).'
      : 'in questo blocco NESSUNA scena puo\' essere "typo".') +
    ' Tutte le altre scene di questo blocco NON possono essere "typo": per loro segui le regole normali (stock, character, list).';
}

// ANTI-RIPETIZIONE (colonna script_no_repeat): cella vuota = comportamento storico
const NO_REPEAT = String($('Load Channel Config').first().json.script_no_repeat || '').trim().toUpperCase() === 'SI';
// DOSSIER PER BLOCCO (script_no_repeat = SI e dossier con righe "SEZIONE n"):
// ogni blocco riceve SOLO le sue sezioni, cosi' non puo' usare i fatti degli altri blocchi.
// Dossier senza righe "SEZIONE n" = dossier intero, comportamento storico.
let dossierBlocco = String(cur.dossier || '');
let dossierDiviso = false;
if (NO_REPEAT && dossierBlocco && nBlocks >= 2) {
  let corpo = dossierBlocco;
  const iFonti = corpo.search(/^\s*(?:\*\*)?FONTI\s*:/im);
  if (iFonti > 0) corpo = corpo.slice(0, iFonti);
  const reSez = /^[ \t]*(?:#+[ \t]*)?(?:\*\*)?SEZIONE[ \t]*(\d{1,2})\b/gim;
  const inizi = [];
  let mSez;
  while ((mSez = reSez.exec(corpo)) !== null) inizi.push(mSez.index);
  if (inizi.length >= 2) {
    const sezioni = inizi.map((p, i) => corpo.slice(p, i + 1 < inizi.length ? inizi[i + 1] : corpo.length).trim());
    const S = sezioni.length;
    const da = Math.floor(b * S / nBlocks);
    const a = Math.max(da + 1, Math.floor((b + 1) * S / nBlocks));
    dossierBlocco = sezioni.slice(da, a).join('\n\n');
    dossierDiviso = true;
    console.log('Blocco ' + (b + 1) + '/' + nBlocks + ': sezioni del dossier ' + (da + 1) + '-' + a + ' di ' + S);
  }
}

let bloccoGiaDetto = '';
if (NO_REPEAT) {
  // tutto il testo gia' scritto (non solo gli ultimi 1500 caratteri)
  let giaScritto = allSegments.map(s => String(s.testo_italiano || '').trim()).filter(Boolean).join(' ');
  if (giaScritto.length > 14000) giaScritto = giaScritto.slice(-14000);
  // numeri gia' usati nel parlato e nei grafici
  const numeri = new Set();
  allSegments.forEach(s => {
    const txt = String(s.testo_italiano || '') + ' ' + String(s.etichetta_scena || '');
    const js = JSON.stringify(s.dati_scena || {});
    (txt.match(/\d+(?:[.,]\d+)*/g) || []).concat(js.match(/\d+(?:\.\d+)?/g) || [])
      .forEach(n => { if (n.replace(/\D/g, '').length >= 2) numeri.add(n); });
  });
  // sezioni del dossier assegnate a questo blocco (dossier con sezioni numerate 1., 2., ...)
  let focusSezioni = '';
  const nums = (String(cur.dossier || '').match(/^\s*(?:#+\s*)?(?:\*\*)?(?:SEZIONE\s*)?(\d{1,2})[.)]/gim) || [])
    .map(x => parseInt(x.replace(/\D/g, ''), 10)).filter(n => n >= 1 && n <= 20);
  const S = nums.length ? Math.max(...nums) : 0;
  if (!dossierDiviso && S >= 2 && nBlocks >= 2) {
    const da = Math.floor(b * S / nBlocks) + 1;
    const a = Math.max(da, Math.floor((b + 1) * S / nBlocks));
    focusSezioni = 'SEZIONI DEL DOSSIER DA USARE IN QUESTO BLOCCO: ' + (da === a ? 'la ' + da : 'dalla ' + da + ' alla ' + a) +
      '. Le altre sezioni sono di altri blocchi: toccale solo per un collegamento di poche parole.\n';
  }
  if (b === 0 || !allSegments.length) {
    bloccoGiaDetto = focusSezioni ? '\n\n' + focusSezioni.trim() : '';
  } else bloccoGiaDetto =
    '\n\nREGOLA ANTI-RIPETIZIONE (PRIORITARIA): chi ascolta si accorge subito se un concetto torna. ' +
    'Sotto trovi TUTTO il testo gia\' detto nel video. In questo blocco ogni scena deve portare un fatto, un numero o un\'idea NUOVI. ' +
    'VIETATO ridire un concetto gia\' detto, anche con parole diverse, sinonimi o da un altro punto di vista. ' +
    'VIETATO riusare un numero gia\' usato come dato principale di una scena o di un grafico; puoi solo richiamarlo in meno di 6 parole per collegarlo a un dato nuovo. ' +
    'Se il dossier per questo blocco finisce, approfondisci il COME e il PERCHE\' dei fatti nuovi, non ripetere quelli vecchi.\n' +
    focusSezioni +
    (numeri.size ? 'NUMERI GIA\' USATI: ' + Array.from(numeri).slice(0, 150).join(', ') + '\n' : '') +
    'TESTO GIA\' DETTO NEL VIDEO:\n' + giaScritto;
}

const lastScenes = allSegments.slice(-2)
  .map(s => '(scena ' + s.scena + ') ' + (s.testo_italiano||'')).join('  |  ');

// ruolo del blocco nell'arco narrativo: serve solo in modalita' titolo,
// perche' senza trascrizione i blocchi non hanno una porzione di testo che li distingua
function faseArco(i, n) {
  if (n === 1) return 'L\'INTERO VIDEO: hook, sviluppo e chiusura dentro queste scene.';
  if (i === 0) return 'APERTURA: hook forte e presentazione del tema. Non bruciare subito tutti i dati migliori.';
  if (i === n - 1) return 'CHIUSURA: ultimo dato forte, sintesi e riflessione finale rivolta allo spettatore.';
  return 'SVILUPPO (parte ' + i + ' di ' + (n - 2) + '): approfondisci aspetti del dossier NON ancora usati nel riassunto.';
}

const intestazioneTitolo = modoTitolo
  ? 'MODALITA\' PRODUZIONE DA TITOLO (PRIORITARIA SULLE ISTRUZIONI DI SISTEMA):\n' +
    'LINGUA: scrivi TUTTO in ' + LINGUA + ', ogni scena, ogni etichetta, il titolo. Gli script di riferimento sono in un\'altra lingua: NON imitarne la lingua, MAI.\n' +
    'Questo video NON adatta nessun video esistente: non c\'e\' trascrizione. Lo scrivi DA ZERO sul tema del titolo "' + cur.titoloOriginale + '".\n' +
    'Ovunque le istruzioni di sistema parlano di "trascrizione originale" o di "materiale originale", intendi il DOSSIER VERIFICATO riportato sotto: e\' la tua UNICA fonte di fatti.\n' +
    'Ogni numero, percentuale, data, nome di studio o di ricercatore deve comparire nel DOSSIER. Se un dato non c\'e\', usa un concetto invece di una cifra. Vietato inventare.\n' +
    'Nei "dati_scena" riporta il valore ESATTO del dossier, decimali compresi: se il dossier dice 46,9% scrivi 46.9, MAI 47. La scritta e il grafico devono mostrare lo stesso identico numero.\n' +
    'Nelle scene con "dati_scena" la scritta "etichetta_scena" NON ripete il numero: dice COSA si sta misurando (es. "I BATTITI DEL TUO CUORE"); il numero sta solo nel grafico, e l\'etichetta del grafico aggiunge il contesto (es. "a 30 anni"). Mai la stessa informazione due volte sullo schermo.\n' +
    'Quando il dossier lo permette, preferisci un grafico "barre" con 2 o 3 valori da confrontare (es. a 30 anni / a 80 anni) a un numero isolato: un confronto fa capire, un numero da solo si dimentica.\n' +
    'Gli script di riferimento parlano di ALTRI argomenti: da li\' prendi SOLO ritmo, tono e tecniche narrative, MAI temi, esempi o contenuti.\n' +
    'Ruolo di questo blocco nel video: ' + faseArco(b, nBlocks) + '\n\n'
  : '';

// REGOLE DEL CANALE (colonne formula_canale, domande_commenti, copia_copione): celle vuote = comportamento storico
const _cfgC = $('Load Channel Config').first().json;
const FORMULA = String(_cfgC.formula_canale || '').trim();
const NDOM = parseInt(_cfgC.domande_commenti) || 0;
const COPIA = Number(String(_cfgC.copia_copione ?? '').replace(',', '.').replace('%', '')) || 0;
let regolaCanale = '';
if (FORMULA) regolaCanale += '\n\nFORMULA DEL CANALE (PRIORITARIA): ' + FORMULA;
   if (COPIA >= 100 && !modoTitolo) regolaCanale += '\n\nQUOTA DI COPIA (PRIORITARIA): segui l\'originale al 100%: stessi concetti, stesso ordine, stessi esempi, stesse domande, stessi ganci. Riscrivi solo le parole (sinonimi, frasi unite o divise) per non essere una copia identica. NON aggiungere contenuti nostri.';
   else if (COPIA > 0 && COPIA < 100 && !modoTitolo) regolaCanale += '\n\nQUOTA DI COPIA (PRIORITARIA): segui l\'originale per circa il ' + COPIA + '% (stessi concetti, stesso ordine, stessi esempi chiave). Il restante ' + (100 - COPIA) + '% e\' nostro: chiarimenti utili, esempi concreti, frasi che rendono il concetto piu\' applicabile, sempre coerenti con il tema.';
if (NDOM > 0) {
  const posDom = [];
  for (let k = 1; k <= NDOM; k++) posDom.push(Math.max(2, Math.round(Number(cur.total) * k / (NDOM + 1))));
  const quiDom = posDom.filter(n => n >= sceneFrom && n <= sceneTo);
  regolaCanale += '\n\nDOMANDE PER I COMMENTI (PRIORITARIA): ' + (quiDom.length
    ? 'alla fine della scena ' + quiDom.join(' e della scena ') + ' inserisci UNA domanda diretta a chi ascolta, legata a quello che si sta dicendo in quel momento, che lo invita a rispondere nei commenti (breve e naturale, mai generica). Nelle altre scene di questo blocco nessun invito a commentare.'
    : 'in questo blocco NESSUN invito a commentare.');
}
const user =
intestazioneTitolo +
'[BLOCCO ' + (b + 1) + ' di ' + nBlocks + ']\n' +
'Genera ESATTAMENTE le scene da ' + sceneFrom + ' a ' + sceneTo + ' (' + scenesThisBlock + ' scene), ognuna ' + cur.wordRange + ' parole.\n' +
(b === 0
  ? 'Questo e\' il PRIMO blocco: la scena ' + sceneFrom + ' deve essere l\'hook forte. Includi anche "titolo_italiano" = il titolo del video scritto in ' + LINGUA + ', come tutto il resto del video (il nome del campo e\' storico, NON significa italiano).' + (String($('Load Channel Config').first().json.title_copy_competitor || 'SI').trim().toUpperCase() === 'SI' && String(cur.titoloOriginale || '').trim() ? ' REGOLA TITOLO (PRIORITARIA): il titolo_italiano parte da questo titolo originale di successo: "' + String(cur.titoloOriginale).trim() + '". Deve restare QUASI IDENTICO: stessa struttura e lunghezza, stesse parole d\'apertura (es. Ranking, Top 10), stessi numeri, stessi luoghi, stesse PAROLE SCRITTE IN MAIUSCOLO e stessi separatori (- | :). Cambia SOLO 1 o 2 parole con sinonimi naturali (es. Towns -> Places, Most -> Top). Vietato accorciarlo, togliere il numero o le maiuscole. Se l\'originale e\' in un\'altra lingua, traducilo in ' + LINGUA + ' mantenendo tutto il resto.' : '')     + (String($('Load Channel Config').first().json.title_character_rule || '').trim() ? ' REGOLA PERSONAGGIO (PRIORITARIA, vale anche sul titolo): ' + String($('Load Channel Config').first().json.title_character_rule).trim() : '') + (String($('Load Channel Config').first().json.render_character_auto || '').trim() ? ' PERSONAGGIO DEL VIDEO (OBBLIGATORIO): nel JSON aggiungi anche il campo "personaggio_video" = UNA descrizione in inglese di 50-80 parole della persona di questa epoca (' + String($('Load Channel Config').first().json.render_character_auto).trim() + ') piu adatta a rappresentare QUESTO video sullo schermo, scelta in base al tema del titolo e della storia: per esempio un gladiatore, un legionario, un imperatore, un senatore, un fornaio, un mercante, una guardia, uno schiavo, un medico, una nobildonna, una sacerdotessa, una principessa. Descrivi: ruolo, uomo o donna, eta, fisico, volto, capelli o barba, espressione adatta alla storia, abiti e accessori fedeli all epoca, cosa tiene in mano, se e in piedi o seduto. Niente sfondo, niente testo.' : '') + '\n'
  : 'CONTINUA la narrazione dal punto in cui era rimasta. NON ripartire da capo, NON ripetere concetti gia\' detti, NON rifare l\'hook.\n') +
'\nRIASSUNTO DI QUANTO GIA\' RACCONTATO (per coerenza, non ripeterlo):\n' + (runningSummary || '(niente, e\' l\'inizio del video)') +
bloccoGiaDetto +
'\n\nULTIME SCENE PRODOTTE (devi proseguire da qui senza stacchi):\n' + (lastScenes || '(nessuna)') +
(modoTitolo
  ? '\n\nLEVE PSICOLOGICHE DA USARE (soprattutto nei primi 60s):\n'
  : '\n\nLEVE PSICOLOGICHE DEL COMPETITOR (replica soprattutto nei primi 60s):\n') + cur.bias +
'\n\nSCRIPT DI RIFERIMENTO (impara lo STILE, non copiare):\n' + cur.referenceBlock +
(cur.dossier
  ? (dossierDiviso
      ? '\n\nDOSSIER VERIFICATO - SOLO LE SEZIONI ASSEGNATE A QUESTO BLOCCO (UNICA fonte di fatti e numeri per queste scene; il resto del dossier e\' riservato agli altri blocchi e NON va usato). Usa tutti i dati di queste sezioni, ognuno UNA volta sola; quando sono finiti approfondisci il COME e il PERCHE\', non ripetere:\n'
      : (modoTitolo
          ? '\n\nDOSSIER VERIFICATO (UNICA fonte di fatti e numeri per questo video):\n'
          : '\n\nDOSSIER VERIFICATO SULL\'AZIENDA (fonte autorizzata: usala per date, cifre e tappe):\n')) + dossierBlocco
  : '') +
(modoTitolo
  ? '\n\nTRASCRIZIONE: nessuna. Costruisci il racconto dal titolo e dal DOSSIER.'
  : '\n\nPORZIONE DI TRASCRIZIONE DA TRASFORMARE IN QUESTO BLOCCO:\n' + cur.slice) +
(modoTitolo
  ? '\n\nPROMEMORIA FINALE: tutto il testo delle scene va scritto in ' + LINGUA + '. Nessuna parola in altre lingue.'
  : '') +
regolaTypo + regolaCanale + '\n\nNumera le scene a partire ESATTAMENTE da ' + sceneFrom + '.\n' +
(CAPITOLI
  ? 'Il campo "capitolo" e\' il titolo di questo blocco come capitolo del video su YouTube: massimo 40 caratteri, in ' + LINGUA + ', concreto, dice di cosa parla il blocco (es. "Il mito dei 21 giorni"), senza numeri d\'ordine e senza emoji.\n'
  : '') +
'Restituisci SOLO un oggetto JSON valido, niente testo extra, niente markdown:\n' +
(b === 0
  ? (CAPITOLI ? '{"titolo_italiano":"...","capitolo":"...","segments":[ ... ]}' : '{"titolo_italiano":"...","segments":[ ... ]}')
  : (CAPITOLI ? '{"capitolo":"...","segments":[ ... ]}' : '{"segments":[ ... ]}')) +
'\nOgni scena: {"scena":N,"testo_italiano":"...","prompt_immagine_inglese":"The character... , absolutely no text, no words, no labels, no captions, no titles, no signs, no writing of any kind in the image","render_mode":"character","stock_query":"","list_items":[],"etichetta_scena":"","dati_scena":{}}';

return [{ json: {
  anthropicBody: {
    model: 'claude-sonnet-4-6',
    max_tokens: 8000,
       system: [{ type: 'text', text: systemMessage, cache_control: { type: 'ephemeral' } }],
    messages: [{ role: 'user', content: user }]
  },
  // mi porto dietro i metadati del blocco per i nodi successivi
  blockIndex: b,
  nBlocks: nBlocks,
  sceneFrom: sceneFrom,
  total: cur.total,
  titoloOriginale: cur.titoloOriginale
}}];

// ============================================================
//  "Accumula Blocco" — RETRY DI BLOCCO + salvataggio per-scena
//  1) parse pulito (ideale, 0 perdite)
//  2) se malformato e ci sono tentativi -> RE-RICHIEDI il blocco a Claude
//     (JSON valido, 0 scene perse, discorso intatto)
//  3) solo dopo MAX retry -> salvataggio per-scena (ultima spiaggia)
// ============================================================
const resp = $json;
const meta = $('Costruisci Prompt Blocco').first().json;
const MAX_BLOCK_RETRIES = 3;

const wfStatic = $getWorkflowStaticData('global');
if (!wfStatic.allSegments) wfStatic.allSegments = [];
if (!wfStatic.runningSummary) wfStatic.runningSummary = '';
if (!wfStatic.titolo) wfStatic.titolo = '';
if (!wfStatic.blockRetries) wfStatic.blockRetries = {};

let raw = '';
try { raw = (resp && resp.content && resp.content[0] && resp.content[0].text || '').trim(); } catch (e) { raw = ''; }
raw = raw.replace(/^```json\s*/i, '').replace(/^```\s*/, '').replace(/```\s*$/, '').trim();
const fb = raw.indexOf('{'), lb = raw.lastIndexOf('}');
if (fb >= 0 && lb > fb) raw = raw.slice(fb, lb + 1);

const stripTrailingCommas = (s) => s.replace(/,\s*([}\]])/g, '$1');

let parsed = null;
for (const cand of [raw, stripTrailingCommas(raw)]) {
  try { parsed = JSON.parse(cand); break; } catch (e) {}
}

function accetta(titolo, segs, capitolo) {
  if (meta.blockIndex === 0 && titolo) wfStatic.titolo = titolo;
    if (meta.blockIndex === 0) wfStatic.personaggio = String((parsed && parsed.personaggio_video) || '').trim();
  let sceneFrom = wfStatic.allSegments.length + 1;
  // CAPITOLI YouTube: salva il titolo del blocco (arriva solo con youtube_chapters_enabled = SI)
  if (!Array.isArray(wfStatic.capitoli)) wfStatic.capitoli = [];
  const cap = String(capitolo || '').replace(/\s+/g, ' ').trim();
  if (cap && segs.length) wfStatic.capitoli.push({ scena: sceneFrom, titolo: cap.slice(0, 60) });
  segs.forEach((s, i) => { s.scena = sceneFrom + i; });
  wfStatic.allSegments = wfStatic.allSegments.concat(segs);
  wfStatic.runningSummary = (wfStatic.runningSummary + ' ' + segs.map(s => s.testo_italiano || '').join(' ')).slice(-1500);
  wfStatic.total = meta.total;
  wfStatic.titoloOriginale = meta.titoloOriginale;
  return [{ json: { __retry: false, blockDone: meta.blockIndex + 1, nBlocks: meta.nBlocks, sceneFinora: wfStatic.allSegments.length, capitoliFinora: wfStatic.capitoli.length } }];
}

// CASO IDEALE: JSON pulito -> accetta tutto, 0 perdite
if (parsed && Array.isArray(parsed.segments) && parsed.segments.length) {
  // LIMITE PAROLE (colonna scene_word_limit = SI): troppe scene lunghe -> RE-RICHIEDO il blocco (max 2 volte)
  const WL = String($('Load Channel Config').first().json.scene_word_limit || '').trim().toUpperCase() === 'SI';
  if (WL) {
    let maxW = 0;
    try {
      const wr = String($('Prepara Blocchi').all()[meta.blockIndex].json.wordRange || '');
      maxW = parseInt(wr.split('-')[1] || wr, 10) || 0;
    } catch (e) {}
    if (maxW > 0) {
      const lunghe = parsed.segments.filter((s, i) => !(meta.blockIndex === 0 && i === 0)
        && String(s.testo_italiano || '').trim().split(/\s+/).filter(Boolean).length > maxW + 3).length;
      const kw = 'w' + meta.blockIndex;
      const fatti = wfStatic.blockRetries[kw] || 0;
      if (lunghe > parsed.segments.length * 0.2 && fatti < 2) {
        wfStatic.blockRetries[kw] = fatti + 1;
        const body = JSON.parse(JSON.stringify(meta.anthropicBody));
        try {
          const last = body.messages[body.messages.length - 1];
          last.content += '\n\nIMPORTANTE (LUNGHEZZA): nel tentativo precedente ' + lunghe + ' scene superavano ' + maxW +
            ' parole. OGNI scena deve avere AL MASSIMO ' + maxW + ' parole: UNA sola frase breve per scena. ' +
            'Se un concetto e\' lungo, dividilo su piu\' scene consecutive. Un dato o un numero per scena. Conta le parole prima di rispondere.';
        } catch (e) {}
        console.log('Blocco ' + (meta.blockIndex + 1) + ': ' + lunghe + ' scene oltre ' + maxW + ' parole, RE-RICHIEDO (tentativo ' + (fatti + 1) + '/2).');
        return [{ json: { __retry: true, anthropicBody: body } }];
      }
    }
  }
  return accetta(parsed.titolo_italiano || null, parsed.segments, parsed.capitolo);
}

// JSON malformato: RE-RICHIEDI il blocco (se restano tentativi)
const key = String(meta.blockIndex);
const done = wfStatic.blockRetries[key] || 0;
if (done < MAX_BLOCK_RETRIES) {
  wfStatic.blockRetries[key] = done + 1;
  const body = JSON.parse(JSON.stringify(meta.anthropicBody)); // copia profonda
  try {
    const msgs = body.messages;
    const last = msgs[msgs.length - 1];
    last.content += '\n\nIMPORTANTE (RIGORE JSON): restituisci ESCLUSIVAMENTE un oggetto JSON valido e COMPLETO. Ogni virgoletta doppia dentro i testi va scappata con \\". Nessun a-capo letterale dentro le stringhe: usa spazi. Nessun testo fuori dal JSON, niente markdown.';
  } catch (e) {}
  console.log('Blocco ' + (meta.blockIndex + 1) + '/' + meta.nBlocks + ': JSON malformato, RE-RICHIEDO il blocco (tentativo ' + (done + 1) + '/' + MAX_BLOCK_RETRIES + ').');
  return [{ json: { __retry: true, anthropicBody: body } }];
}

// ULTIMA SPIAGGIA: dopo MAX retry, salvataggio per-scena
function segmentsBody(s) {
  const k = s.indexOf('"segments"'); if (k < 0) return null;
  let i = s.indexOf('[', k); if (i < 0) return null;
  const start = i; let depth = 0, inStr = false, esc = false;
  for (; i < s.length; i++) { const ch = s[i];
    if (inStr) { if (esc) esc = false; else if (ch === '\\') esc = true; else if (ch === '"') inStr = false; continue; }
    if (ch === '"') { inStr = true; continue; }
    if (ch === '[') depth++; else if (ch === ']') { depth--; if (depth === 0) return s.slice(start + 1, i); }
  }
  return s.slice(start + 1);
}
function topLevelObjects(body) {
  const out = []; let depth = 0, st = -1, inStr = false, esc = false;
  for (let i = 0; i < body.length; i++) { const ch = body[i];
    if (inStr) { if (esc) esc = false; else if (ch === '\\') esc = true; else if (ch === '"') inStr = false; continue; }
    if (ch === '"') { inStr = true; continue; }
    if (ch === '{') { if (depth === 0) st = i; depth++; }
    else if (ch === '}') { depth--; if (depth === 0 && st >= 0) { out.push(body.slice(st, i + 1)); st = -1; } }
  }
  return out;
}
let titolo = null;
const mt = raw.match(/"titolo_italiano"\s*:\s*"((?:[^"\\]|\\.)*)"/);
if (mt) titolo = mt[1];
const bodyStr = segmentsBody(raw);
const objs = bodyStr ? topLevelObjects(bodyStr) : [];
const segs = []; let scartate = 0;
for (const o of objs) {
  let obj = null;
  for (const cand of [o, stripTrailingCommas(o)]) { try { obj = JSON.parse(cand); break; } catch (e) {} }
  if (obj && (obj.testo_italiano !== undefined || obj.scena !== undefined || obj.prompt_immagine_inglese !== undefined)) segs.push(obj);
  else scartate++;
}
console.log('Blocco ' + (meta.blockIndex + 1) + '/' + meta.nBlocks + ': dopo ' + MAX_BLOCK_RETRIES + ' retry, salvataggio per-scena: ' + segs.length + ' recuperate, ' + scartate + ' scartate.');
if (!segs.length) {
  throw new Error('Blocco ' + (meta.blockIndex + 1) + '/' + meta.nBlocks + ': nessuna scena recuperata dopo ' + MAX_BLOCK_RETRIES + ' retry. Inizio risposta: ' + raw.slice(0, 200));
}
const mc = raw.match(/"capitolo"\s*:\s*"((?:[^"\\]|\\.)*)"/);
return accetta(titolo, segs, mc ? mc[1] : '');

// Tutti i blocchi sono finiti: impacchetto lo stato accumulato nel
// formato IDENTICO al vecchio Agent, cosi' la coda non cambia.
const wfStatic = $getWorkflowStaticData('global');
let allSegments = wfStatic.allSegments || [];
const total = wfStatic.total || allSegments.length;
const titolo = wfStatic.titolo || wfStatic.titoloOriginale || 'Video';
const nBlocks = Math.ceil(total / (parseInt($('Load Channel Config').first().json.scene_per_blocco) || 20));

// taglio di sicurezza al totale esatto
allSegments = allSegments.slice(0, total);
// TEST BREVI (target_durata che inizia con "test_"): ogni scena viene tagliata a fine frase
// entro il massimo di parole previsto, cosi' un test da 1 minuto dura davvero ~1 minuto.
// Righe vere (breve_, medio_, lungo_...): nessun cambiamento.
const _target = String($('Read Production Row').first().json.target_durata || '').trim();
if (_target.startsWith('test_')) {
  let maxW = 0;
  try {
    const wr = String($('Prepara Blocchi').first().json.wordRange || '');
    maxW = parseInt(wr.split('-')[1] || wr, 10) || 0;
  } catch (e) {}
  if (maxW > 0) {
    allSegments = allSegments.map(s => {
      const txt = String(s.testo_italiano || '').trim();
      const frasi = txt.split(/(?<=[.!?])\s+/).filter(Boolean);
      let out = '';
      for (const f of frasi) {
        const prova = (out + ' ' + f).trim();
        if (prova.split(/\s+/).length > maxW) break;
        out = prova;
      }
            if (!out) out = frasi[0] || txt;   // mai frasi tagliate a meta': meglio una scena un po' piu' lunga
      return { ...s, testo_italiano: out };
    });
    console.log('Test breve (' + _target + '): scene tagliate a max ' + maxW + ' parole');
  }
}
const outputObj = {
  titolo_italiano: titolo,
    personaggio_video: wfStatic.personaggio || '',
  note_riferimenti: 'Generato a blocchi (loop n8n, ' + nBlocks + ' blocchi). Totale ' + allSegments.length + ' scene.',
segments: allSegments,
  capitoli: wfStatic.capitoli || []
};

// SALVO l'output nello static GLOBAL: i nodi a valle lo leggeranno da qui,
// senza dipendere da $node["AI Scriptwriter"] (fragile dopo un loop).
const sdGlobal = $getWorkflowStaticData('global');
sdGlobal.scriptOutput = outputObj;

return [{ json: { output: outputObj } }];

// ============================================================
//  Estrai Copertina Competitor
//  Dal "Link video" (foglio produzione) ricava l'URL della copertina
//  YouTube del competitor e prepara il payload vision per GPT-4.1.
//  PARAMETRICO: thumbnail_copy_competitor = SI attiva; vuoto = OFF (storico).
//               thumbnail_max_words = numero max parole (default 4).
//  Emette SEMPRE un item (mai []), altrimenti bloccherebbe il SEO Generator.
// ============================================================

const cfg = $('Load Channel Config').first().json;
const row = $('Read Production Row').first().json;

const _flag    = String(cfg.thumbnail_copy_competitor || 'SI').trim().toUpperCase();
const ATTIVO   = (_flag === 'SI' || _flag === 'SPUNTO');
const MODO     = _flag === 'SPUNTO' ? 'spunto' : (_flag === 'SI' ? 'copia' : 'off');
const MAX_WORDS = parseInt(cfg.thumbnail_max_words) || 4;
const LANG     = String(cfg.language || '').trim().toLowerCase();
const LANG_NAME = LANG === 'it' ? 'italiano' : (cfg.language_name || LANG || 'italiano');

// --- estrai video id da qualsiasi formato YouTube ---
const link = String(row['Link video'] || row.link_video || '').trim();
let vid = '';
const patterns = [
  /[?&]v=([A-Za-z0-9_-]{11})/,
  /youtu\.be\/([A-Za-z0-9_-]{11})/,
  /\/shorts\/([A-Za-z0-9_-]{11})/,
  /\/embed\/([A-Za-z0-9_-]{11})/
];
for (const p of patterns) { const m = link.match(p); if (m) { vid = m[1]; break; } }

if (!ATTIVO || !vid) {
  console.log(`[CopiaCompetitor] OFF (attivo=${ATTIVO}, video_id="${vid}") -> SEO Generator usa la logica storica`);
return [{ json: { attivo: false, modo: MODO, motivo: !ATTIVO ? 'disattivato' : 'video_id non trovato nel link' } }];
}

// hqdefault esiste SEMPRE (maxresdefault solo se il video e' HD)
const thumbUrl = `https://i.ytimg.com/vi/${vid}/hqdefault.jpg`;

const valuta = LANG === 'it' ? 'Se nel testo compare il simbolo $ o la parola "dollars/dollari", CONVERTILO in € (euro). Adatta anche eventuali cifre al formato italiano (es. 50.000 €).' : '';

// thumbnail_copy_scene = FOTO -> descrive la FOTO del competitor (luogo, persone, oggetti) per rifarla simile ma nuova.
// SI o vuoto = brief storico per illustratore (KAO).
const FOTO = String(cfg.thumbnail_copy_scene || '').trim().toUpperCase() === 'FOTO';
const PUNTO3 = FOTO
  ? `3. DESCRIVI LA FOTO in inglese nel campo scena_idea_en (90-140 parole), come brief per un fotografo che deve scattare una foto NUOVA molto SIMILE ma NON identica: (a) il tipo di luogo (strada asfaltata o sterrata, case di legno/mattoni/stile western/pastello, negozi, murales), la regione e il clima che suggerisce (deserto, sud rurale, Florida, New England), la stagione e la vegetazione; (b) lo stato del posto (curato, abbandonato, rifiuti, erbacce, crepe); (c) le PERSONE: quante sono, dove stanno nell'inquadratura (primo piano, mezzo, sfondo), cosa fanno, la postura, l'abbigliamento generico; se nella foto non ci sono persone scrivilo; (d) auto, oggetti e simboli visibili (bandiera americana, auto d'epoca, sedie a dondolo), descritti in modo generico; (e) inquadratura, altezza della camera, luce, cielo, colori dominanti. Poi applica 2 MICRO-VARIAZIONI per non copiare: sposta leggermente il punto di vista (es. un lato della strada invece del centro), cambia case e auto con altre dello stesso tipo, cambia di una unita' il numero di persone o la loro posizione. Mai volti riconoscibili di persone reali, mai armi, polizia, sangue o simboli d'odio (al posto della bandiera confederata usa una bandiera americana sbiadita). NON citare il testo della copertina e NON descrivere loghi o scritte.`
  : `3. DESCRIVI L'IDEA DELLA SCENA in inglese nel campo scena_idea_en (60-100 parole), come brief per un illustratore che deve creare una scena NUOVA e ORIGINALE con lo stesso significato, NON una copia: (a) quanti personaggi e il loro ruolo; (b) l'azione, la posa generica e l'emozione del personaggio principale; (c) quali oggetti simbolici raccontano il titolo, descritti in modo generico (es. "a birthday cake with one candle", non colori, decorazioni o dettagli precisi); (d) eventuali simboli grafici usati (frecce, punti interrogativi, cuori); (e) NON descrivere lo sfondo della copertina: proponi invece UN luogo reale e quotidiano dove questa situazione accade nella vita vera (es. "a living room during a small family birthday party", "a kitchen in the evening", "a bedroom at night"). NON descrivere lo stile di disegno del competitor, NON descrivere il suo personaggio (sara' sostituito dal nostro), NON citare il testo della copertina.`;

const systemPrompt = `Sei un esperto di copertine YouTube. Ti do la copertina di un video ${'competitor'} che ha avuto molto successo.

COMPITO:
1. LEGGI il testo scritto dentro la copertina (solo il testo grande in evidenza, ignora loghi, watermark, durata, nomi canale).
2. TRADUCILO in ${LANG_NAME}.

REGOLE OBBLIGATORIE:
- MASSIMO ${MAX_WORDS} parole. Questo limite e' TASSATIVO: se la traduzione letterale e' piu' lunga, accorciala mantenendo il senso e la leva emotiva. Articoli, preposizioni, congiunzioni e possessivi NON contano nel limite. Il titolo deve sempre essere una frase di senso compiuto: mai troncata a meta'. La frase deve essere SEMPRE grammaticalmente corretta e naturale in ${LANG_NAME}: MAI togliere articoli, preposizioni o parole necessarie per stare nel limite (articoli e preposizioni NON contano). Esempi: "PIOGGIA TUTTA LA SETTIMANA", mai "PIOGGIA TUTTA SETTIMANA"; "NON GUARDANO IL MONDIALE", mai "NON GUARDANO MONDIALE"; in inglese "THE TOWN THAT DIED", mai "TOWN THAT DIED".
- Usa la formulazione piu' NATURALE e COMUNE in ${LANG_NAME}: le parole che una persona vera userebbe e digiterebbe cercando questo argomento. Preferisci termini comuni e diretti a sinonimi ricercati o traduzioni letterali goffe.
- Mantieni la stessa struttura dell'originale (se e' una domanda resta una domanda, se e' un'affermazione resta un'affermazione).
- TUTTO MAIUSCOLO.
- ${valuta}
- Se nella copertina NON c'e' testo leggibile, restituisci testo_originale: "" e titolo_thumbnail_it: "".

${PUNTO3}

Rispondi SOLO con questo JSON, niente altro:
{"testo_originale":"...","titolo_thumbnail_it":"...","scena_idea_en":"..."}`;

const payload = {
  model: 'gpt-4.1',
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: [
      { type: 'text', text: 'Leggi il testo di questa copertina, descrivi l\'idea della scena e applica le regole.' },
      { type: 'image_url', image_url: { url: thumbUrl, detail: 'high' } }
    ]}
  ],
  max_tokens: 700,
  temperature: 0.4
};

console.log(`[CopiaCompetitor] ON | video_id=${vid} | max_words=${MAX_WORDS} | ${thumbUrl}`);
return [{ json: { attivo: true, modo: MODO, video_id: vid, thumb_url: thumbUrl, payload } }];

// ============================================================
//  Parse Copertina Competitor
//  Legge la risposta OpenAI vision ed estrae il titolo tradotto.
//  Applica un taglio HARD al max parole (rete di sicurezza se l'AI sfora).
//  onError=continue a monte: se la vision fallisce, qui esce titolo vuoto
//  e il SEO Generator torna alla logica storica.
// ============================================================

const cfg = $('Load Channel Config').first().json;
const MAX_WORDS = parseInt(cfg.thumbnail_max_words) || 4;

let raw = '';
try {
  raw = $json.choices?.[0]?.message?.content || '';
} catch (e) { raw = ''; }

let parsed = { testo_originale: '', titolo_thumbnail_it: '' };
if (raw) {
  const clean = String(raw).replace(/```json/gi, '').replace(/```/g, '').trim();
  try { parsed = JSON.parse(clean); }
  catch (e) {
    const m = clean.match(/\{[\s\S]*\}/);
    if (m) { try { parsed = JSON.parse(m[0]); } catch (e2) {} }
  }
}

let titolo = String(parsed.titolo_thumbnail_it || '').trim().toUpperCase();

// rete di sicurezza: il limite conta solo le parole PIENE.
// Articoli, preposizioni, congiunzioni e possessivi non occupano spazio concettuale
// e tagliarli a meta' produce frasi monche tipo "SALVA I TUOI".
const VUOTE = new Set(['il','lo','la','i','gli','le','un','uno','una','di','a','da','in','con','su','per','tra','fra','del','dello','della','dei','degli','delle','al','allo','alla','ai','agli','alle','dal','dalla','dai','nel','nella','nei','negli','nelle','sul','sulla','sui','e','ed','o','che','non','tuo','tua','tuoi','tue','mio','mia','miei','mie','suo','sua','suoi','sue','the','an','of','to','on','at','for','with','and','or','by','from','your','my','his','her','its','our','their','this','that','is','are']);
const piena = (w) => !VUOTE.has(w.toLowerCase().replace(/[^\p{L}']/gu, ''));

const words = titolo.split(/\s+/).filter(Boolean);
const piene = words.filter(piena).length;
if (piene > MAX_WORDS) {
  const out = [];
  let count = 0;
  for (const w of words) {
    if (piena(w)) {
      if (count === MAX_WORDS) break;
      count++;
    }
    out.push(w);
  }
  // non chiudere mai su una parola vuota: "SALVA I TUOI" -> "SALVA"
  while (out.length && !piena(out[out.length - 1])) out.pop();
  titolo = out.join(' ');
  console.log(`[CopiaCompetitor] sforato (${piene} parole piene) -> tagliato a ${MAX_WORDS}: "${titolo}"`);
}

console.log(`[CopiaCompetitor] originale="${parsed.testo_originale}" -> IT="${titolo}"`);
return [{ json: { titolo_thumbnail_competitor: titolo, testo_originale: String(parsed.testo_originale || ''), scena_idea_en: String(parsed.scena_idea_en || '').trim() } }];

// ============================================================
//  Build Prompt Manuale  (v6 — SOLO PERSONAGGIO + EMOZIONE)
//  AB genera un prompt che produce SOLO il personaggio, grande,
//  su sfondo pulito ritagliabile, con l'ESPRESSIONE decisa dal
//  SEO Generator in base a titolo + bias + copertina competitor.
//  Niente scena, niente oggetti, niente soldi, niente freccia,
//  niente titolo, niente copy, niente URL.
//  Il resto della copertina lo monta Giorgio in Canva.
//  Il ref del personaggio si allega a mano in Gemini.
// ============================================================
const cfg = $('Load Channel Config').first().json;

const seo = $('SEO Generator').isExecuted
  ? $('SEO Generator').first().json.output
  : ($('Carica Checkpoint').first().json.seo || {});

// emozione decisa dal SEO Generator (nuovo campo). Vuoto = neutra.
const emozione = (seo.thumbnail_character_emotion || '').toString().trim();

// copy competitor: NON entra nel prompt, esce solo in colonna AC
let copy = '';
try {
  if ($('Parse Copertina Competitor').isExecuted) {
    copy = $('Parse Copertina Competitor').first().json.titolo_thumbnail_competitor || '';
  }
} catch (e) { copy = ''; }

const stile = cfg.thumbnail_color_style
  || '2D flat cartoon style, clean thick black outlines, vivid saturated colors, flat fills, no shading, no gradients, no realistic rendering, YouTube thumbnail style';

const NOTEXT = 'absolutely no text, no words, no letters, no numbers, no labels, no captions, no titles, no signs, no logos, no watermark, no writing of any kind anywhere in the image';

const OUTFIT_LOCKED = (cfg.character_outfit_locked === true
  || String(cfg.character_outfit_locked).toLowerCase() === 'true');

const REF = OUTFIT_LOCKED
  ? 'Use the attached image as the character reference: keep the exact same character and the exact same drawing style as the reference, same thick black outlines, same flat colors, same cartoon proportions, same face, same hair, same beard, same outfit, same apparent age'
  : 'Use the attached image ONLY as a STYLE reference: keep the exact same drawing style (same thick black outlines, same flat colors, same cartoon proportions), the same face type and apparent age. The OUTFIT, clothing, headwear and accessories MUST match the video topic and the historical/contextual setting described - do NOT copy the outfit from the reference image';

// espressione: dal SEO Generator se c'e', altrimenti neutra amichevole
const espressione = emozione
  ? ('The character has a clear, strong, readable facial expression: ' + emozione + ', matching the topic of the video')
  : 'The character has a friendly confident expression';

const SOGGETTO = 'Draw ONLY this single character, alone, large and centered, shown from the head down to the mid-thigh, facing forward. ' + espressione + '. The character must be the only element in the image: no objects, no props, no money, no arrows, no scenery, no background decoration. Plain solid flat neutral background (light grey or white), completely empty, so the character can be easily cut out. Full character clearly inside the frame, not cropped at the edges, generous empty margin around the character';

const promptEN = [
  NOTEXT,
  REF,
  SOGGETTO,
  stile,
  'One single character, one single 16:9 image, 1280x720, one subject only, not a grid, not a collage, no multiple variants, no borders, no frame',
  NOTEXT
].join('. ') + '.';

return [{ json: { prompt_copertina_manuale: promptEN, copy_competitor_it: copy } }];

