={{ (() => {
  const cfg = $('Load Channel Config').first().json;
  const seo = $('SEO Generator').isExecuted ? $('SEO Generator').first().json.output : $('Carica Checkpoint').first().json.seo;
  let desc = (seo["descrizione_youtube"] || "").replace(/\\n/g, "\n");
  const sw = $('AI Scriptwriter').isExecuted ? $('AI Scriptwriter').first().json.output : ($('Carica Checkpoint').first().json.scriptwriter || {});
  const caps = Array.isArray(sw.capitoli) ? sw.capitoli.slice().sort((a, b) => a.scena - b.scena) : [];
  const segs = Array.isArray(sw.segments) ? sw.segments : [];
