  if (String(cfg.youtube_chapters_enabled || '').trim().toUpperCase() === 'SI' && caps.length >= 3 && dur > 0 && segs.length) {
    const len = s => String(s.testo_italiano || s.text || '').length;
    const tot = segs.reduce((a, s) => a + len(s), 0) || 1;
    const prima = n => segs.filter(s => Number(s.scena) < n).reduce((a, s) => a + len(s), 0);
    const fmt = t => Math.floor(t / 60) + ':' + String(Math.floor(t % 60)).padStart(2, '0');
    const righe = [];
    let ultimo = -100;
    caps.forEach((c, i) => {
      const t = i === 0 ? 0 : Math.max(0, Math.floor(dur * prima(Number(c.scena)) / tot) - 1);
      if (t - ultimo < 10) return;
      righe.push(fmt(t) + ' ' + String(c.titolo || '').replace(/\s+/g, ' ').trim());
      ultimo = t;
    });
    if (righe.length >= 3) desc += '\n\nCapitoli:\n' + righe.join('\n');
  }
  if (cfg.youtube_description_footer) desc += '\n\n' + cfg.youtube_description_footer;
  return desc;
})() }}

