// Pick Texture — MODE: Run Once for Each Item
// Due ingressi possibili:
//  a) Switch Render Mode uscita "typo"  -> scena tipografica pianificata
//  b) Texture di riserva? uscita true   -> scena stock rimasta senza footage Pexels
const src = $json;
const config = $('Load Channel Config').first().json;

const textures = String(config.scene_bg_textures || '')
  .split(',')
  .map(s => s.trim())
  .filter(s => s.length > 0);

if (textures.length === 0) {
  throw new Error('scene_bg_textures e vuoto per channel_id=' + config.channel_id);
}

// la scena puo' arrivare gia' ri-stampata (fallback) o dentro l'oggetto scena (typo)
let scena = Number(src.scena) || Number(src.index) || 0;
let etichetta = String(src.etichetta_scena || '').trim();

// se manca qualcosa, la ripesco dalla scena classificata (item linking)
if (!scena || !etichetta) {
  const cs = $('Classify scenes').item.json;
  if (!scena) scena = Number(cs.scena) || Number(cs.index) || 1;
  if (!etichetta) etichetta = String(cs.etichetta_scena || '').trim();
}

const fallback = src.pexels_found === false && !src.video_url;
if (fallback) {
  console.log('Scena ' + scena + ': Pexels a vuoto, ripiego su texture tipografica.');
}

return {
  scena: scena,
  video_url: textures[(scena - 1) % textures.length],
  pexels_found: false,
  is_texture: true,
  texture_fallback: fallback,
  etichetta_scena: etichetta
};

// Pick Texture Fallback — MODE: Run Once for Each Item
// UN SOLO ingresso: Texture di riserva? uscita true
// Gemello di Pick Texture: esiste solo per evitare che UN nodo abbia due rami
// entranti (n8n lo eseguirebbe due volte e il merge a valle perderebbe scene).
const src = $json;
const config = $('Load Channel Config').first().json;

const textures = String(config.scene_bg_textures || '')
  .split(',')
  .map(s => s.trim())
  .filter(s => s.length > 0);

if (textures.length === 0) {
  throw new Error('scene_bg_textures e vuoto per channel_id=' + config.channel_id);
}

// la scena puo' arrivare gia' ri-stampata (fallback) o dentro l'oggetto scena (typo)
let scena = Number(src.scena) || Number(src.index) || 0;
let etichetta = String(src.etichetta_scena || '').trim();

// se manca qualcosa, la ripesco dalla scena classificata (item linking)
if (!scena || !etichetta) {
  const cs = $('Classify scenes').item.json;
  if (!scena) scena = Number(cs.scena) || Number(cs.index) || 1;
  if (!etichetta) etichetta = String(cs.etichetta_scena || '').trim();
}

const fallback = src.pexels_found === false && !src.video_url;
if (fallback) {
  console.log('Scena ' + scena + ': Pexels a vuoto, ripiego su texture tipografica.');
}

return {
  scena: scena,
  video_url: textures[(scena - 1) % textures.length],
  pexels_found: false,
  is_texture: true,
  texture_fallback: fallback,
  etichetta_scena: etichetta
};

// Nessuna Trascrizione
// Ramo FALSE di IF Modalita: la riga non ha Link video.
// Il video si scrive dal titolo e dal dossier di ricerca web.
// Restituisco una trascrizione vuota con la stessa forma di HTTP Request3,
// cosi' Merge e i nodi a valle non si accorgono della differenza.
return [{ json: { transcript: [], origine_contenuto: 'titolo' } }];

// Raccogli Foto Cornice — unisce le foto Pexels ai dati del video.
// Esce SEMPRE un solo item = dati di Collect Card URLs + frame_photos {indice_scena: url}
// + chart_photos {indice_scena: url} (foto del soggetto per le scene grafico, colonna chart_photo).
// Ogni foto Pexels viene usata UNA sola volta nel video (niente stessa foto su piu' grafici).
const base = $('Collect Card URLs').first().json;
const frame_photos = {};
const chart_photos = {};
const usate = new Set();
let reqs = [];
try { reqs = $('Prepara Foto Cornice').all(); } catch (e) { reqs = []; }
const res = $input.all();
const lum = (h) => { const m = String(h || '').match(/^#?([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/i); return m ? (0.299 * parseInt(m[1], 16) + 0.587 * parseInt(m[2], 16) + 0.114 * parseInt(m[3], 16)) : 128; };
res.forEach((r, i) => {
  const meta = reqs[i] && reqs[i].json;
  if (!meta || meta._sentinel) return;
  const ph = (r.json && Array.isArray(r.json.photos)) ? r.json.photos : [];
  if (!ph.length) return;
  const dest = meta.chart ? chart_photos : frame_photos;
  const chiare = ph.filter(x => lum(x.avg_color) >= 80);
  const pool = (meta.chart && chiare.length) ? chiare : ph;
  // la prima foto non ancora usata; se sono tutte gia' usate, salto (meglio grafico senza foto che foto ripetuta)
  const p = pool.find(x => !usate.has(x.id)) || ph.find(x => !usate.has(x.id));
  if (!p) return;
  const url = p.src ? (p.src.large2x || p.src.large || p.src.original) : '';
  if (url) { dest[String(meta.idx)] = url; usate.add(p.id); }
});
console.log('Foto in cornice trovate: ' + Object.keys(frame_photos).length + ', foto per grafici: ' + Object.keys(chart_photos).length);
return [{ json: { ...base, frame_photos, chart_photos } }];

// Prepara Render GitHub — v2: due formati.
//  - render_workflow vuoto o filosofo.yml  -> formato "filosofo" (Agora of Sages), IDENTICO a prima.
//  - render_workflow = kao_render.yml      -> formato "kao": scene (testo + voce + tipo), config del canale; le clip le sceglie GitHub (100% Pexels con i controlli).
// Esce con il file JSON delle scene (binario "data") da caricare su Drive.
const cfg = $('Load Channel Config').first().json;
const j2v = $input.first().json;
const src = $('Carica Checkpoint').isExecuted ? $('Carica Checkpoint').first().json : $('Raccogli Foto Cornice').first().json;
const arr = (v) => Array.isArray(v) ? v : [v];
const testi = arr(src.testo_scena), audios = arr(src.url_audio);
const WF = String(cfg.render_workflow || 'filosofo.yml').trim();
const sw = $('AI Scriptwriter').isExecuted ? $('AI Scriptwriter').first().json.output : ($('Carica Checkpoint').first().json.scriptwriter || {});
let stile = {};
try { stile = JSON.parse(String(cfg.render_style || '').trim() || '{}'); } catch (e) { console.log('render_style non e JSON valido, ignorata'); }
const iscrizione = {
  img: String(cfg.subscribe_overlay_url || '').trim(),
  sec: cfg.subscribe_overlay_second,
  clic: String(cfg.subscribe_overlay_sound_url || '').trim(),
  clic_ritardo: cfg.subscribe_overlay_sound_delay,
  campana: String(cfg.subscribe_overlay_bell_url || '').trim(),
  campana_ritardo: cfg.subscribe_overlay_bell_delay,
};
const id = String($execution.id);
let dati;

if (WF.toLowerCase().includes('kao')) {
  // ===== formato KAO =====
  const isTypos = arr(src.is_typo), etichette = arr(src.etichetta_scena), datiScena = arr(src.dati_scena);
  let query = [];
  try { query = $('Classify scenes').all().map(i => String(i.json.stock_query || '')); } catch (e) { query = []; }   // solo suggerimento: le ricerche vere le scrive GitHub
  const ok = (u) => /^https?:\/\/\S+$/i.test(String(u || '').trim()) && !String(u).includes('undefined') && !String(u).endsWith('id=');
  const scene = [];
  testi.forEach((t, i) => {
    if (!ok(audios[i])) { console.log('Scena ' + (i + 1) + ' senza audio valido: scartata'); return; }
    const typo = isTypos[i] === true || isTypos[i] === 'true';
    scene.push({ testo: String(t || ''), audio: String(audios[i]).trim(), typo, etichetta: typo ? String(etichette[i] || '') : '',
      dati: typo && datiScena[i] && typeof datiScena[i] === 'object' ? datiScena[i] : {}, stock_query: query[i] || '' });
  });
  // EFFETTI DI JSON2VIDEO (colonna effetti_github = SI): grafici, cornici, titoli, cifre e suoni, presi dal JSON gia' pronto
  if (String(cfg.effetti_github || '').trim().toUpperCase() === 'SI') {
    const perVoce = {};
    for (const sc of (j2v.scenes || [])) {
      const els = sc.elements || [];
      const voce = els.find(e => e.type === 'audio' && e.start === undefined && e.src);
      if (voce) perVoce[String(voce.src).trim()] = { sc, els, voce: String(voce.src).trim() };
    }
    const swoosh = String(cfg.transition_sound_url || '').trim();
    let nEff = 0;
    for (const s of scene) {
      const x = perVoce[s.audio]; if (!x) continue;
      const primo = x.els[0] || {};
      const eff = {
        sfondo: x.sc['background-color'] || '',
        cornice: primo.type === 'html' ? primo : null,
        livelli: x.els.slice(1).filter(e => e.type === 'html' || e.type === 'text' || (e.type === 'video' && Number(e.start) > 0)),
        suoni: x.els.filter(e => e.type === 'audio' && String(e.src || '').trim() !== x.voce && String(e.src || '').trim() !== swoosh)
          .map(e => ({ src: e.src, start: Number(e.start) || 0, volume: e.volume ?? 1, durata: Number(e.duration) > 0 ? Number(e.duration) : 0 }))
      };
      if (eff.cornice || eff.livelli.length || eff.suoni.length) { s.effetti = eff; nEff++; }
    }
    console.log('Effetti json2video passati a GitHub: ' + nEff + ' scene');
  }
  if (!scene.length) throw new Error('Render GitHub KAO: nessuna scena con voce.');
  const prendi = ['channel_id', 'channel_name', 'language', 'show_subtitles', 'subtitle_font_family', 'subtitle_font_size', 'subtitle_word_color',
    'subtitle_line_color', 'subtitle_outline_color', 'subtitle_outline_width', 'subtitle_max_words_per_line', 'subtitle_replace',
    'stock_clip_duration', 'stock_media_type', 'stock_query_suffix', 'stock_exclude_words', 'regole_immagini',
    'scene_bg_textures', 'thumbnail_font_url', 'brand_font_family', 'thumbnail_highlight_text_color', 'thumbnail_highlight_stroke_color',
    'thumbnail_highlight_stroke_width', 'typo_stroke_width', 'typo_text_style', 'chart_bar_color', 'chart_value_color',
    'transition_sound_url', 'transition_sound_volume', 'transition_sound_percentage', 'end_screen_seconds', 'end_screen_text',
    'musica_rotazione', 'musica_volume', 'effetti_github'];
  const config = {};
  for (const k of prendi) if (cfg[k] !== undefined && cfg[k] !== null && String(cfg[k]).trim() !== '') config[k] = cfg[k];
  const _mus = (j2v.elements || []).find(e => e.type === 'audio' && e.start === undefined && e.src);
  dati = { formato: 'kao', id, titolo: sw.titolo_italiano || '', scene, iscrizione, config, stile,
    musica: _mus ? _mus.src : '', volume_musica: _mus ? (Number(_mus.volume) || 0.035) : 0 };
  console.log('Render GitHub KAO: ' + scene.length + ' scene, ' + scene.filter(s => s.typo).length + ' tipografiche');
} else {
  // ===== formato filosofo (Agora): invariato =====
  const testoDi = {};
  audios.forEach((a, i) => { if (a) testoDi[String(a).trim()] = String(testi[i] || ''); });
  const scene = [];
  for (const sc of (j2v.scenes || [])) {
    const els = sc.elements || [];
    const voce = els.find(e => e.type === 'audio' && e.start === undefined && e.src);
    if (!voce) continue;
    const media = els
      .filter(e => (e.type === 'video' || e.type === 'image') && Number(e.width) === 1920 && e.src)
      .map(e => ({ src: String(e.src).trim(), start: Number(e.start) || 0, tipo: e.type }))
      .sort((a, b) => a.start - b.start);
    scene.push({ testo: testoDi[String(voce.src).trim()] || '', audio: String(voce.src).trim(), media });
  }
  if (!scene.length) throw new Error('Render GitHub: nessuna scena con voce nel payload.');
  const senzaTesto = scene.filter(s => !s.testo).length;
  if (senzaTesto) console.log('Attenzione: ' + senzaTesto + ' scene senza testo (sottotitolo vuoto).');
  const musica = (j2v.elements || []).find(e => e.type === 'audio' && e.start === undefined && e.src);
  dati = {
    iscrizione,
    titolo: sw.titolo_italiano || '',
    personaggio: String(sw.personaggio_video || cfg.render_character || '').trim(),
    personaggio_auto: !!String(sw.personaggio_video || '').trim(),
    personaggio_riserva: String(cfg.render_character || '').trim(),
    scene,
    musica: musica ? musica.src : '',
    volume_musica: musica ? (Number(musica.volume) || 0.08) : 0,
    stile,
         // impostazioni del canale per lo stile "Stoic Journal" (render_style.visivi = pexels_libreria): regole immagini, logo, musica
       config: Object.fromEntries(['language', 'channel_name', 'regole_immagini', 'stock_query_suffix', 'stock_exclude_words', 'thumbnail_watermark_url',
         'musica_rotazione', 'musica_volume', 'domande_commenti'].filter(k => cfg[k] !== undefined && cfg[k] !== null && String(cfg[k]).trim() !== '').map(k => [k, cfg[k]])),  
  };
}
const testo = JSON.stringify(dati);
console.log('Render GitHub (' + WF + '): ' + dati.scene.length + ' scene, file dati ' + Math.round(testo.length / 1024) + ' KB');
return [{
  json: { id, nome_file: 'render_' + id + '.json', scene: dati.scene.length, workflow: WF },
  binary: { data: { data: Buffer.from(testo, 'utf8').toString('base64'), mimeType: 'application/json', fileName: 'render_' + id + '.json' } },
}];

// Risultato Render GitHub — GitHub chiama il link di ripresa con {"movie": {...}}.
// done -> prosegue come json2video (Download Final Video); failed o tempo scaduto -> stop con il motivo.
const body = $input.first().json.body || {};
const movie = body.movie || {};
if (movie.status !== 'done' || !movie.url) {
  throw new Error('\u{1F6D1} Render GitHub NON riuscito: ' + (movie.message || 'nessuna risposta entro il tempo massimo') + '\n' +
    'COSA FARE: apri GitHub > repository ambience > Actions > "Video Filosofo" e guarda l\'ultima esecuzione. ' +
    'Poi rimetti la riga su "Pronto" lasciando piena assets_checkpoint: rifara\' solo il montaggio, senza ripagare voce e immagini.');
}
return [{ json: { movie: { status: 'done', url: movie.url, duration: Number(movie.duration) || 0, ritratto_url: movie.ritratto_url || '', scena_url: movie.scena_url || '', project: 'github-' + $execution.id } } }];

// Risultato Copertina GitHub: {copertina:{status,url}} -> ok=true e url per Download Thumbnail.
// Errore o tempo scaduto -> ok=false: si fa la copertina di sempre (il video non resta mai senza copertina).
const b = ($input.first().json || {}).body || {};
const c = b.copertina || {};
if (c.status === 'done' && c.url) return [{ json: { ok: true, url: c.url } }];
console.log('Copertina GitHub non riuscita: ' + (c.message || 'nessuna risposta') + ' -> copertina di sempre');
return [{ json: { ok: false } }];
